Catalog & Search Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(catalog_search_service, "Catalog & Search Service") {
    Component(CatalogController, "Catalog Controller", "Node.js / Express or Spring MVC REST Controller", "Exposes REST and gRPC endpoints for searching books, browsing categories, and retrieving product details.")
    Component(SearchIndexerService, "Search Indexer Service", "Node.js / Java", "Synchronizes product catalogue data and manages indices in AWS OpenSearch for fast keyword matching.")
    Component(CatalogueRepository, "Catalogue Repository", "AWS OpenSearch Client", "Handles data persistence queries and full-text search operations against AWS OpenSearch.")
}

Rel(CatalogController, SearchIndexerService, "Delegates search and query execution")
Rel(SearchIndexerService, CatalogueRepository, "Queries and indexes catalogue data")

@enduml

Recommendation & Review Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Recommendation & Review Service container

System_Ext(aws_elasticache, "AWS ElastiCache (Redis)", "In-memory data store for caching")
System_Ext(aws_dynamodb, "AWS DynamoDB", "NoSQL database for reviews and ratings")

Container_Boundary(rec_review_service, "Recommendation & Review Service") {
    Component(recommendation_engine_component, "Recommendation Engine Component", "Python / FastAPI", "Handles personalized book recommendations using caching.")
    Component(review_management_component, "Review Management Component", "Python / FastAPI", "Manages customer reviews and ratings.")
}

Rel(recommendation_engine_component, aws_elasticache, "TCP / Redis Protocol", "TCP / Redis")
Rel(review_management_component, aws_dynamodb, "HTTPS / AWS SDK", "HTTPS")

@enduml
